/*
 * 월드마블투어 — 마리나라 클라이언트 확장
 *
 * 원작: 끄엔갤(dcinside) JSX 2인용 보드게임 (리루 플랫폼용), 허락 하에 이식.
 * 원글: https://gall.dcinside.com/mgallery/board/view/?id=aiotomechatting&no=10768
 *
 * 아키텍처 노트 (DESIGN.md 참고):
 * - 카드/로어북 필드는 마리나라가 DOMPurify로 살균해 <script>/onclick/iframe이
 *   전부 제거되므로, 원본 JSX(React 훅 + riru.sendMessage)를 그대로 옮길 수 없다.
 * - 대신 이 파일은 살균되지 않는 "클라이언트 확장"으로 실행되며, 규칙 엔진은
 *   전부 여기서 결정론적으로 계산하고(현금·위치·소유·주사위는 절대 LLM에 맡기지
 *   않음), 캐릭터의 주관적 판단(구매/건설/세계여행 목적지)만 태그 프로토콜로
 *   AI에게 위임한다 (§ 캐릭터 결정 프로토콜 참고).
 * - 상태는 chatId별로 localStorage에 저장한다 (브라우저/기기별 분리, v1 한계).
 */

// ══════════════════════════════════════════════════════════════
// 2.3.5 full-page 호환 심 (2026-08-01, marinara-docs-tutor와 동일 패턴)
//
// v2.3.5의 Personal Extensions full-page 런타임은 v2.3.3 편의 헬퍼
// (addStyle / addElement / on / extensionId)를 제공하지 않는다 —
// 대신 실제 페이지 <script>로 실행되므로 document/window/fetch 원본에
// 직접 접근할 수 있다. 아래 심은 구 API 표면을 원본 DOM 위에 재구현하고,
// 생성물 전부를 marinara.onCleanup에 등록해 "언로드 시 자동 정리" 계약을
// 유지한다. 본문 코드는 무수정.
// (marinara는 호스트 래퍼의 매개변수라 재할당 가능:
//  fullPageExtensionSource → run(extension, async (marinara) => { ... }))
// ══════════════════════════════════════════════════════════════
marinara = (() => {
  const host = marinara;
  const shim = {
    extensionId: host.extension.id,

    addStyle(css) {
      const el = document.createElement("style");
      el.textContent = String(css);
      el.dataset.mwtExtension = host.extension.id;
      document.head.appendChild(el);
      host.onCleanup(() => el.remove());
      return el;
    },

    addElement(parent, tag, attrs = {}) {
      const target = typeof parent === "string" ? document.querySelector(parent) : parent;
      if (!target) return null;
      const el = document.createElement(tag);
      for (const [key, value] of Object.entries(attrs)) {
        if (key === "innerHTML") el.innerHTML = value;
        else if (key === "textContent") el.textContent = value;
        else el.setAttribute(key, value);
      }
      target.appendChild(el);
      host.onCleanup(() => el.remove());
      return el;
    },

    on(target, event, handler) {
      const wrapped = (...args) => {
        try {
          return handler(...args);
        } catch (error) {
          host.log.error("[mwt] event handler failed", error);
        }
      };
      target.addEventListener(event, wrapped);
      host.onCleanup(() => target.removeEventListener(event, wrapped));
      return wrapped;
    },
  };
  return Object.freeze(Object.assign(Object.create(null), {
    version: host.version,
    extension: host.extension,
    log: host.log,
    storage: host.storage,
    setTimeout: host.setTimeout,
    clearTimeout: host.clearTimeout,
    setInterval: host.setInterval,
    clearInterval: host.clearInterval,
    onCleanup: host.onCleanup,
  }, shim));
})();

// ───────────────────────── 보드 데이터 ─────────────────────────

const MWT_TILE_COUNT = 18;
const MWT_CIRCLED = ["", "①", "②", "③", "④", "⑤", "⑥", "⑦", "⑧", "⑨", "⑩", "⑪", "⑫", "⑬", "⑭", "⑮", "⑯", "⑰", "⑱"];
const MWT_BUILD_ICON = ["", "🏡", "🏢", "🏨"];
const MWT_BUILD_COST = [100000, 200000, 300000]; // 0→1, 1→2, 2→3
const MWT_RENT_RATE = [0.3, 0.5, 0.8, 1.2]; // 맨땅/별장/빌딩/호텔
const MWT_LIQUIDATE_RATE = 0.7;
const MWT_START_BONUS = 200000;

// 원본 리루 JSX 컴포넌트의 퍼센트 좌표 그대로 재사용 (보드 원본 이미지 도착 시
// 토큰을 이 좌표에 절대 위치로 얹으면 된다 — assets/README 참고).
const MWT_TILE_POS = {
  1: { x: 7.5, y: 13 },
  2: { x: 21.3, y: 13 },
  3: { x: 35.2, y: 13 },
  4: { x: 49.5, y: 13 },
  5: { x: 63.7, y: 13 },
  6: { x: 78, y: 13 },
  7: { x: 92.5, y: 13 },
  8: { x: 92.5, y: 38 },
  9: { x: 92.5, y: 57 },
  10: { x: 92.5, y: 86 },
  11: { x: 79, y: 86 },
  12: { x: 65.5, y: 86 },
  13: { x: 51.5, y: 86 },
  14: { x: 37.5, y: 86 },
  15: { x: 22.5, y: 86 },
  16: { x: 7.5, y: 86 },
  17: { x: 7.5, y: 57 },
  18: { x: 7.5, y: 38 },
};

// 보드 원본 이미지가 준비되면 이 상수를 data:image/webp;base64,... 값으로 채우고
// mwtRenderBoard()가 자동으로 이미지+토큰 오버레이 모드로 전환한다.
// (256KiB CSS 살균 한도가 아니라 1MiB JS 한도를 쓰도록, 반드시 CSS 텍스트가
// 아니라 이 JS 상수 + style.setProperty로 대입할 것 — DESIGN.md 참고.)
const MWT_BOARD_DATA_URI = "data:image/webp;base64,";

const MWT_TILES = {
  1: { name: "출발", type: "start", corner: true },
  2: { name: "서울", type: "city", price: 700000 },
  3: { name: "이벤트", type: "event" },
  4: { name: "파리", type: "city", price: 550000 },
  5: { name: "세금", type: "tax", amount: -250000 },
  6: { name: "로마", type: "city", price: 400000 },
  7: { name: "무인도", type: "island", corner: true },
  8: { name: "바르셀로나", type: "city", price: 450000 },
  9: { name: "이벤트", type: "event" },
  10: { name: "세계여행", type: "worldtour", corner: true },
  11: { name: "런던", type: "city", price: 650000 },
  12: { name: "두바이", type: "city", price: 750000 },
  13: { name: "도쿄", type: "city", price: 600000 },
  14: { name: "싱가포르", type: "city", price: 580000 },
  15: { name: "뉴욕", type: "city", price: 800000 },
  16: { name: "기부재단", type: "donation", amount: -200000, corner: true },
  17: { name: "시드니", type: "city", price: 500000 },
  18: { name: "휴양지", type: "resort", amount: 50000 },
};

function mwtFmt(n) {
  return Math.round(n).toLocaleString("ko-KR");
}

function mwtTileLabel(tileNum) {
  const t = MWT_TILES[tileNum];
  return `${MWT_CIRCLED[tileNum]}${t.name}`;
}

// ───────────────────────── 주사위 (변조 불가) ─────────────────────────

function mwtRollDie(sides = 6) {
  const buf = new Uint32Array(1);
  crypto.getRandomValues(buf);
  return (buf[0] % sides) + 1;
}

function mwtRollDice() {
  const d1 = mwtRollDie(6);
  const d2 = mwtRollDie(6);
  return { d1, d2, sum: d1 + d2, isDouble: d1 === d2 };
}

// ───────────────────────── 상태 모델 (좌석 기반) ─────────────────────────

function mwtStateKey(chatId) {
  return `mwt:${chatId}`;
}

function mwtLoadState(chatId) {
  try {
    const raw = localStorage.getItem(mwtStateKey(chatId));
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object" || !Array.isArray(parsed.seats)) return null;
    return parsed;
  } catch {
    return null;
  }
}

function mwtSaveState(state) {
  // 생명주기 가드: 구 인스턴스가 늦게 끝나며 신 인스턴스의 진행 상태를
  // 덮어쓰는 것을 방지 (해시 교체 → 빠른 재승인 시나리오).
  if (typeof mwtLifecycle !== "undefined" && mwtLifecycle.disposed) return;
  state.updatedAt = new Date().toISOString();
  try {
    localStorage.setItem(mwtStateKey(state.chatId), JSON.stringify(state));
  } catch (error) {
    console.warn("[월드마블투어] 상태 저장 실패", error);
  }
}

function mwtClearState(chatId) {
  try {
    localStorage.removeItem(mwtStateKey(chatId));
  } catch {
    // best-effort
  }
}

function mwtCreateState(chatId, npcCharacterId, npcName) {
  const now = new Date().toISOString();
  return {
    version: 1,
    chatId,
    seats: [
      {
        id: "seat-1",
        kind: "human",
        label: "나",
        characterId: null,
        cash: 2000000,
        position: 1,
        islandTurnsLeft: 0,
        freePassCount: 0,
        bankrupt: false,
      },
      {
        id: "seat-2",
        kind: "character",
        label: npcName || "NPC",
        characterId: npcCharacterId,
        cash: 2000000,
        position: 1,
        islandTurnsLeft: 0,
        freePassCount: 0,
        bankrupt: false,
      },
    ],
    turnOrder: ["seat-1", "seat-2"],
    currentTurnIndex: 0,
    owned: {}, // tileNum -> { seatId, level }
    pendingDecision: null, // { seatId, kind: "buy"|"build"|"worldtour", tileNum, price?, nextLevel?, nextCost? }
    status: "setup", // setup -> coinflip -> in_progress -> finished
    turnNumber: 0,
    log: [],
    settings: { autoRefresh: false },
    createdAt: now,
    updatedAt: now,
  };
}

function mwtSeat(state, seatId) {
  return state.seats.find((s) => s.id === seatId) || null;
}

function mwtCurrentSeat(state) {
  return mwtSeat(state, state.turnOrder[state.currentTurnIndex]);
}

function mwtOtherSeat(state, seatId) {
  // v1 is strictly 2-seat; this is the one seam that would need to become a
  // list/selector when a future version supports more than 2 seats.
  return state.seats.find((s) => s.id !== seatId) || null;
}

function mwtLog(state, text) {
  state.log.push({ turn: state.turnNumber, text });
  if (state.log.length > 60) state.log.splice(0, state.log.length - 60);
}

// ───────────────────────── 규칙 엔진 ─────────────────────────

function mwtMoveSeat(state, seatId, spaces) {
  const seat = mwtSeat(state, seatId);
  const from = seat.position;
  const total = from + spaces;
  const passedStart = spaces > 0 && total > MWT_TILE_COUNT;
  let to = total % MWT_TILE_COUNT;
  if (to === 0) to = MWT_TILE_COUNT;
  seat.position = to;
  if (passedStart) {
    seat.cash += MWT_START_BONUS;
  }
  return { from, to, passedStart };
}

function mwtTeleportSeat(state, seatId, tileNum) {
  const seat = mwtSeat(state, seatId);
  const from = seat.position;
  seat.position = tileNum;
  return { from, to: tileNum };
}

function mwtLiquidateSeat(state, seatId) {
  const seat = mwtSeat(state, seatId);
  let recovered = 0;
  for (const [tileNumStr, entry] of Object.entries(state.owned)) {
    if (entry.seatId !== seatId) continue;
    const tileNum = Number(tileNumStr);
    const price = MWT_TILES[tileNum].price;
    recovered += Math.round(price * MWT_LIQUIDATE_RATE);
    delete state.owned[tileNum];
  }
  seat.cash += recovered;
  return recovered;
}

function mwtCheckBankruptcy(state, seatId) {
  const seat = mwtSeat(state, seatId);
  if (seat.cash >= 0) return false;
  const recovered = mwtLiquidateSeat(state, seatId);
  mwtLog(state, `${seat.label}이(가) 보유 도시를 전부 매각(${mwtFmt(recovered)}원 회수)했지만 잔고가 부족합니다.`);
  if (seat.cash < 0) {
    seat.bankrupt = true;
    state.status = "finished";
    const winner = mwtOtherSeat(state, seatId);
    mwtLog(state, `${seat.label} 파산 — 게임 종료. 승자: ${winner.label}`);
    return true;
  }
  return false;
}

function mwtApplyRent(state, payerSeatId, ownerSeatId, tileNum) {
  const payer = mwtSeat(state, payerSeatId);
  const owner = mwtSeat(state, ownerSeatId);
  if (payer.freePassCount > 0) {
    payer.freePassCount -= 1;
    return { text: `${payer.label}는 통행료 면제권을 사용했습니다 (${mwtTileLabel(tileNum)}).`, amount: 0 };
  }
  const level = state.owned[tileNum].level;
  const amount = Math.round(MWT_TILES[tileNum].price * MWT_RENT_RATE[level]);
  payer.cash -= amount;
  owner.cash += amount;
  const bankrupted = mwtCheckBankruptcy(state, payerSeatId);
  return {
    text: `${payer.label}가 ${owner.label} 소유 ${mwtTileLabel(tileNum)}(${MWT_BUILD_ICON[level] || "맨땅"})에 도착 — 통행료 ₩${mwtFmt(amount)} 지불.`,
    amount,
    bankrupted,
  };
}

function mwtEventRoll(state, seatId) {
  const roll = mwtRollDie(7);
  const seat = mwtSeat(state, seatId);
  switch (roll) {
    case 1:
      seat.cash += 300000;
      return { text: `이벤트 ①: ${seat.label} +₩300,000`, needsDecision: null };
    case 2:
      seat.cash += 150000;
      return { text: `이벤트 ②: ${seat.label} +₩150,000`, needsDecision: null };
    case 3:
      seat.cash -= 200000;
      mwtCheckBankruptcy(state, seatId);
      return { text: `이벤트 ③: ${seat.label} −₩200,000`, needsDecision: null };
    case 4: {
      mwtTeleportSeat(state, seatId, 1);
      return { text: `이벤트 ④: ${seat.label}가 출발 칸으로 이동합니다 (통과 보너스 없음).`, needsDecision: null };
    }
    case 5: {
      mwtTeleportSeat(state, seatId, 7);
      seat.islandTurnsLeft = 2;
      return { text: `이벤트 ⑤: ${seat.label}가 무인도로 이동, 2턴 정지합니다.`, needsDecision: null };
    }
    case 6:
      seat.freePassCount += 1;
      return { text: `이벤트 ⑥: ${seat.label}가 통행료 면제권을 획득했습니다.`, needsDecision: null };
    case 7: {
      const coin = mwtRollDie(2); // 1=홀(지급) 개념으로 짝수/홀수 판정을 위해 별도 처리
      const oddPays = mwtRollDie(6) % 2 === 1;
      const other = mwtOtherSeat(state, seatId);
      if (oddPays) {
        seat.cash -= 150000;
        other.cash += 150000;
        mwtCheckBankruptcy(state, seatId);
        return { text: `이벤트 ⑦: 주사위 홀 — ${seat.label}가 ${other.label}에게 ₩150,000 지급.`, needsDecision: null };
      }
      seat.cash += 150000;
      other.cash -= 150000;
      mwtCheckBankruptcy(state, other.id);
      return { text: `이벤트 ⑦: 주사위 짝 — ${seat.label}가 ${other.label}로부터 ₩150,000 수령.`, needsDecision: null };
    }
    default:
      return { text: "이벤트: (알 수 없음)", needsDecision: null };
  }
}

// 착지 처리. seat가 방금 이동해 도착한 타일을 해석해 상태를 갱신하고,
// { text, decision } 를 반환한다. decision이 있으면 호출부가 사람 UI 또는
// AI 태그 프로토콜로 후속 결정을 받아야 한다.
function mwtResolveTile(state, seatId) {
  const seat = mwtSeat(state, seatId);
  const tileNum = seat.position;
  const tile = MWT_TILES[tileNum];
  const owned = state.owned[tileNum];

  switch (tile.type) {
    case "start":
      return { text: `${seat.label}가 ${mwtTileLabel(tileNum)}에 도착.` };
    case "tax":
      seat.cash += tile.amount;
      mwtCheckBankruptcy(state, seatId);
      return { text: `${seat.label} 세금 칸 도착: ${mwtFmt(tile.amount)}원.` };
    case "donation":
      seat.cash += tile.amount;
      mwtCheckBankruptcy(state, seatId);
      return { text: `${seat.label} 기부재단 도착: ${mwtFmt(tile.amount)}원.` };
    case "resort":
      seat.cash += tile.amount;
      return { text: `${seat.label} 휴양지 도착: +₩${mwtFmt(tile.amount)}.` };
    case "island":
      seat.islandTurnsLeft = 2;
      return { text: `${seat.label}가 무인도에 도착, 2턴 정지합니다.` };
    case "event": {
      const result = mwtEventRoll(state, seatId);
      return { text: `${mwtTileLabel(tileNum)} — ${result.text}` };
    }
    case "worldtour":
      return {
        text: `${seat.label}가 세계여행 칸에 도착 — 목적지를 선택합니다.`,
        decision: { kind: "worldtour", tileNum },
      };
    case "city": {
      if (!owned) {
        if (seat.cash < tile.price) {
          return { text: `${seat.label}가 ${mwtTileLabel(tileNum)}(₩${mwtFmt(tile.price)})에 도착했지만 잔고 부족으로 구매할 수 없습니다.` };
        }
        return {
          text: `${seat.label}가 미소유 ${mwtTileLabel(tileNum)}(₩${mwtFmt(tile.price)})에 도착했습니다.`,
          decision: { kind: "buy", tileNum, price: tile.price },
        };
      }
      if (owned.seatId === seatId) {
        if (owned.level >= 3) {
          return { text: `${seat.label}가 본인 소유 ${mwtTileLabel(tileNum)}(호텔, 최대 등급)에 도착.` };
        }
        const nextCost = MWT_BUILD_COST[owned.level];
        if (seat.cash < nextCost) {
          return { text: `${seat.label}가 본인 소유 ${mwtTileLabel(tileNum)}에 도착했지만 건설 자금이 부족합니다.` };
        }
        return {
          text: `${seat.label}가 본인 소유 ${mwtTileLabel(tileNum)}에 도착 — 건설 여부를 결정합니다 (다음 단계 ${MWT_BUILD_ICON[owned.level + 1]}, ₩${mwtFmt(nextCost)}).`,
          decision: { kind: "build", tileNum, nextLevel: owned.level + 1, nextCost },
        };
      }
      const rent = mwtApplyRent(state, seatId, owned.seatId, tileNum);
      return { text: rent.text };
    }
    default:
      return { text: `${seat.label}가 ${mwtTileLabel(tileNum)}에 도착.` };
  }
}

// 결정을 적용하고 { text, followUpDecision } 를 반환한다. followUpDecision은
// 세계여행으로 도착한 칸이 그 자체로 또 다른 결정(구매/건설)을 요구할 때만
// 채워진다 — 호출부가 이를 새 pendingDecision으로 이어 붙여야 한다.
function mwtApplyDecision(state, seatId, decision, rawValue) {
  const seat = mwtSeat(state, seatId);
  const value = String(rawValue || "").trim().toLowerCase();

  if (decision.kind === "buy") {
    if (value === "yes" && seat.cash >= decision.price) {
      seat.cash -= decision.price;
      state.owned[decision.tileNum] = { seatId, level: 0 };
      return { text: `${seat.label}가 ${mwtTileLabel(decision.tileNum)}을(를) ₩${mwtFmt(decision.price)}에 구매했습니다.`, followUpDecision: null };
    }
    return { text: `${seat.label}는 ${mwtTileLabel(decision.tileNum)} 구매를 포기했습니다.`, followUpDecision: null };
  }

  if (decision.kind === "build") {
    if (value === "yes" && seat.cash >= decision.nextCost) {
      seat.cash -= decision.nextCost;
      state.owned[decision.tileNum].level = decision.nextLevel;
      return {
        text: `${seat.label}가 ${mwtTileLabel(decision.tileNum)}에 ${MWT_BUILD_ICON[decision.nextLevel]}을(를) 건설했습니다 (₩${mwtFmt(decision.nextCost)}).`,
        followUpDecision: null,
      };
    }
    return { text: `${seat.label}는 ${mwtTileLabel(decision.tileNum)} 건설을 보류했습니다.`, followUpDecision: null };
  }

  if (decision.kind === "worldtour") {
    const target = Number(value);
    if (Number.isInteger(target) && target >= 1 && target <= MWT_TILE_COUNT && target !== decision.tileNum) {
      mwtTeleportSeat(state, seatId, target);
      const followUp = mwtResolveTile(state, seatId);
      return {
        text: `${seat.label}가 세계여행으로 ${mwtTileLabel(target)}을(를) 선택했습니다. ${followUp.text}`,
        followUpDecision: followUp.decision ? { ...followUp.decision } : null,
      };
    }
    return { text: `${seat.label}는 세계여행 목적지를 정하지 못해 그 자리에 머뭅니다.`, followUpDecision: null };
  }

  return { text: "", followUpDecision: null };
}

function mwtDecisionDefault(decision) {
  if (decision.kind === "buy") return "no";
  if (decision.kind === "build") return "no";
  if (decision.kind === "worldtour") return String(decision.tileNum);
  return "";
}

function mwtDecisionPrompt(seat, decision) {
  if (decision.kind === "buy") {
    return (
      `[월드마블투어 상태] ${seat.label} 현재 위치 ${mwtTileLabel(decision.tileNum)}(미소유, 구매가 ₩${mwtFmt(decision.price)}). 잔고 ₩${mwtFmt(seat.cash)}.\n` +
      `성격과 판돈 상황(내기 여부)에 맞춰 구매 여부를 스스로 정하고, 대사에 이유를 드러내세요.`
    );
  }
  if (decision.kind === "build") {
    return (
      `[월드마블투어 상태] ${seat.label} 현재 위치 ${mwtTileLabel(decision.tileNum)}(본인 소유). 다음 단계 ${MWT_BUILD_ICON[decision.nextLevel]}, 비용 ₩${mwtFmt(decision.nextCost)}. 잔고 ₩${mwtFmt(seat.cash)}.\n` +
      `건설 여부를 성격에 맞게 정하고 대사에 이유를 드러내세요.`
    );
  }
  if (decision.kind === "worldtour") {
    const options = Array.from({ length: MWT_TILE_COUNT }, (_, i) => i + 1)
      .filter((n) => n !== decision.tileNum)
      .map((n) => `${n}=${mwtTileLabel(n)}`)
      .join(", ");
    return (
      `[월드마블투어 상태] ${seat.label}가 세계여행 칸에 도착했습니다. 성격에 맞게 목적지를 하나 고르세요.\n` +
      `선택지(타일 번호로 답할 것): ${options}`
    );
  }
  return "";
}

function mwtTagInstruction(decision) {
  const example =
    decision.kind === "worldtour" ? `[marble-decision: worldtour=<1~18 중 하나>]` : `[marble-decision: ${decision.kind}=yes]` + ` 또는 ` + `[marble-decision: ${decision.kind}=no]`;
  return `응답 마지막 줄에 다른 텍스트 없이 반드시 아래 형식의 태그만 단독으로 추가하세요:\n${example}`;
}

// ───────────────────────── 마리나라 API 연동 ─────────────────────────

// marinara.apiFetch (packages/client/src/components/layout/CustomThemeInjector.tsx)
// always resolves the parsed JSON body internally and does not expose status
// codes — unusable for our SSE /generate calls and for our .ok/.status checks.
// Extensions have full same-origin `fetch` access as a real page module, so we
// call the API directly instead and get a normal Response back.
async function mwtApi(path, options) {
  // 생명주기 가드: 비활성화 후에는 새 서버 쓰기(채팅 append·생성 비용)를
  // 시작하지 않고, 진행 중 요청은 abort 신호로 함께 끊는다.
  if (mwtLifecycle.disposed) throw new Error("월드마블투어가 비활성화되어 요청을 중단했습니다.");
  return window.fetch(`/api/${String(path).replace(/^\/+/, "")}`, {
    ...(options ?? {}),
    signal: mwtLifecycle.abort.signal,
  });
}

async function mwtPostMessage(chatId, role, content, characterId) {
  const res = await mwtApi(`chats/${encodeURIComponent(chatId)}/messages`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ role, characterId: characterId ?? null, content }),
  });
  if (!res.ok) throw new Error(`메시지 전송 실패 (HTTP ${res.status})`);
  return res.json();
}

async function mwtGenerateForCharacter(chatId, characterId) {
  const res = await mwtApi("generate", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ chatId, userMessage: null, forCharacterId: characterId, streaming: false }),
  });
  const text = await res.text();
  if (!res.ok) throw new Error(`생성 요청 실패 (HTTP ${res.status}): ${text.slice(0, 200)}`);
  const errorMatch = text.match(/"type"\s*:\s*"error"[^}]*"data"\s*:\s*"([^"]*)"/);
  if (errorMatch) throw new Error(`생성 실패: ${errorMatch[1]}`);
  if (!/"type"\s*:\s*"done"/.test(text)) throw new Error("생성 완료 신호(done)를 받지 못했습니다.");
  return true;
}

async function mwtGetMessages(chatId) {
  const res = await mwtApi(`chats/${encodeURIComponent(chatId)}/messages`, { headers: { Accept: "application/json" } });
  if (!res.ok) throw new Error(`메시지 조회 실패 (HTTP ${res.status})`);
  return res.json();
}

// GET /:id/messages returns oldest-first (packages/server/src/services/storage/chats.storage.ts
// orders by createdAt ascending) — take from the end for "newest".
async function mwtGetLatestAssistantMessage(chatId, characterId) {
  const list = await mwtGetMessages(chatId);
  for (let i = list.length - 1; i >= 0; i -= 1) {
    const m = list[i];
    if (m.role === "assistant" && (!characterId || m.characterId === characterId)) return m;
  }
  return null;
}

const MWT_DECISION_RE = /\[marble-decision:\s*([a-z-]+)=([^\]]+)\]\s*$/i;

function mwtParseDecisionTag(content) {
  const trimmed = (content || "").trim();
  const match = trimmed.match(MWT_DECISION_RE);
  if (!match) return null;
  return { key: match[1].toLowerCase(), value: match[2].trim() };
}

// 위젯 로그에 남길 대사만 남기고 [marble-decision: ...] 태그 줄은 잘라낸다.
function mwtStripDecisionTag(content) {
  return (content || "").trim().replace(MWT_DECISION_RE, "").trim();
}

// 캐릭터에게 주관적 결정을 요청한다: narrator 프롬프트 전송 → /generate → 최신
// assistant 메시지에서 [marble-decision: ...] 태그 파싱. 실패 시 1회 정정
// 재시도 후 안전한 기본값으로 폴백 (게임이 절대 멈추지 않도록).
// { value, dialogue } 를 반환한다 — dialogue는 태그를 뗀 캐릭터의 실제 대사로,
// 위젯 로그에 그대로 남겨 채팅창을 새로고침하지 않아도 볼 수 있게 한다.
async function mwtRequestCharacterDecision(state, seat, decision) {
  const prompt = `${mwtDecisionPrompt(seat, decision)}\n\n${mwtTagInstruction(decision)}`;
  await mwtPostMessage(state.chatId, "narrator", prompt, null);
  await mwtGenerateForCharacter(state.chatId, seat.characterId);
  let msg = await mwtGetLatestAssistantMessage(state.chatId, seat.characterId);
  let tag = msg && mwtParseDecisionTag(msg.content);

  if (!tag || tag.key !== decision.kind) {
    await mwtPostMessage(
      state.chatId,
      "narrator",
      `태그 형식이 인식되지 않았습니다. ${mwtTagInstruction(decision)}`,
      null,
    );
    await mwtGenerateForCharacter(state.chatId, seat.characterId);
    msg = await mwtGetLatestAssistantMessage(state.chatId, seat.characterId);
    tag = msg && mwtParseDecisionTag(msg.content);
  }

  if (!tag || tag.key !== decision.kind) {
    const fallback = mwtDecisionDefault(decision);
    await mwtPostMessage(
      state.chatId,
      "narrator",
      `${seat.label}가 결정을 명확히 밝히지 않아 기본값으로 처리합니다.`,
      null,
    );
    return { value: fallback, dialogue: null };
  }
  const dialogue = mwtStripDecisionTag(msg.content);
  return { value: tag.value, dialogue: dialogue || null };
}

// ───────────────────────── 활성 채팅 감지 ─────────────────────────
// marinara-bidi-translate가 이미 쓰는 검증된 패턴: window.fetch를 한 번 래핑해
// /api/chats/<id> 요청을 관찰. 다른 확장의 래퍼와도 델리게이션으로 공존한다.

const mwtOriginalFetch = window.fetch;
let mwtActiveChatId = null;

function mwtFetchUrl(input) {
  if (typeof input === "string") return input;
  if (typeof URL !== "undefined" && input instanceof URL) return input.href;
  if (typeof Request !== "undefined" && input instanceof Request) return input.url;
  return "";
}

// "internal" is excluded because /api/chats/internal/professor-mari/... is a
// literal sub-route (chats.routes.ts), not a chat id — without this guard the
// sniffer would mistake "internal" for the active chat id.
function mwtSniffChatId(url) {
  const match = url.match(/\/api\/chats\/(?!internal(?:\/|$))([^/?]+)/);
  if (match && match[1] !== "undefined") mwtActiveChatId = decodeURIComponent(match[1]);
}

// ── 생명주기 가드 (Codex 검토 2026-08-01) ──
// 비활성화·해시 교체 시 호스트는 UI·리스너·타이머만 정리한다. 진행 중인
// API 호출과 다단계 NPC 턴은 여기서 스스로 중단한다.
const mwtLifecycle = { disposed: false, abort: new AbortController() };

function mwtRoutedFetch(input, init) {
  // disposed 후에는 관찰 없이 위임만 하는 inert delegate — 우리가 체인의
  // head가 아니어서 복원하지 못한 경우에도 무해하게 남는다.
  if (!mwtLifecycle.disposed) mwtSniffChatId(mwtFetchUrl(input));
  return mwtOriginalFetch.call(window, input, init);
}
window.fetch = mwtRoutedFetch;

marinara.onCleanup(() => {
  mwtLifecycle.disposed = true;
  mwtLifecycle.abort.abort();
  // Codex BLOCKER 수정: 다른 확장이 우리 뒤에 fetch를 또 래핑했을 수 있다
  // (예: 체인 native → MWT → 타 확장). 무조건 원본을 대입하면 그 확장의
  // 래퍼까지 우회되므로, 우리가 여전히 head일 때만 복원한다. head가 아니면
  // 위의 inert delegate로 남아 위임만 계속한다.
  if (window.fetch === mwtRoutedFetch) window.fetch = mwtOriginalFetch;
});

marinara.on(window, "marinara:generation-complete", (event) => {
  const chatId = event?.detail?.chatId;
  if (typeof chatId === "string" && chatId) mwtActiveChatId = chatId;
});

async function mwtResolveActiveChatId() {
  if (mwtActiveChatId) return mwtActiveChatId;
  const res = await mwtApi("chats", { headers: { Accept: "application/json" } });
  if (!res.ok) return null;
  const chats = await res.json();
  if (!Array.isArray(chats) || !chats.length) return null;
  const sorted = [...chats].sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime());
  return sorted[0]?.id ?? null;
}

async function mwtGetChat(chatId) {
  const res = await mwtApi(`chats/${encodeURIComponent(chatId)}`, { headers: { Accept: "application/json" } });
  if (!res.ok) throw new Error(`채팅 정보 조회 실패 (HTTP ${res.status})`);
  return res.json();
}

// GET /api/chats/:id returns characterIds as a raw JSON-encoded string (same
// storage-column pattern as `metadata`), not an already-parsed array.
function mwtParseCharacterIds(raw) {
  if (Array.isArray(raw)) return raw;
  if (typeof raw !== "string") return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

// GET /api/characters/:id returns the card's `data` field as a JSON-encoded
// string (character card V2/V3 spec) — the display name lives at data.name,
// not top-level. Returns { id, name } or null.
async function mwtGetCharacter(characterId) {
  const res = await mwtApi(`characters/${encodeURIComponent(characterId)}`, { headers: { Accept: "application/json" } });
  if (!res.ok) return null;
  const raw = await res.json();
  let name = raw?.id;
  try {
    const data = typeof raw?.data === "string" ? JSON.parse(raw.data) : raw?.data;
    if (data && typeof data.name === "string" && data.name.trim()) name = data.name.trim();
  } catch {
    // fall back to id
  }
  return { id: raw?.id, name };
}

