const mwtButton = marinara.addElement(document.body, "button", {
  type: "button",
  class: "mwt-floating-button",
  title: "월드마블투어",
  "aria-label": "월드마블투어 확장 열기",
  textContent: "🎲",
});

const mwtPanel = marinara.addElement(document.body, "section", {
  class: "mwt-panel-layer",
  hidden: "",
  role: "dialog",
  "aria-label": "월드마블투어",
});

if (!mwtButton || !mwtPanel) {
  throw new Error("월드마블투어 위젯 UI를 만들 수 없습니다.");
}

// Device/browser-local UI preference, deliberately separate from chat/game state.
const MWT_BUTTON_POSITION_KEY = "mwt:ui:button-position";
const mwtSafeArea = marinara.addElement(document.body, "div", {
  "aria-hidden": "true",
  style: "position:fixed;visibility:hidden;pointer-events:none;width:0;height:0;padding:env(safe-area-inset-top, 0px) env(safe-area-inset-right, 0px) env(safe-area-inset-bottom, 0px) env(safe-area-inset-left, 0px);",
});
let mwtButtonPosition = null;
try {
  const saved = JSON.parse(localStorage.getItem(MWT_BUTTON_POSITION_KEY));
  if (saved && Number.isFinite(saved.x) && Number.isFinite(saved.y)) {
    mwtButtonPosition = { x: saved.x, y: saved.y };
  }
} catch {
  // Storage can be disabled or contain an invalid old value.
}

function mwtButtonBounds() {
  const viewport = window.visualViewport;
  const left = viewport?.offsetLeft ?? 0;
  const top = viewport?.offsetTop ?? 0;
  const width = viewport?.width ?? window.innerWidth;
  const height = viewport?.height ?? window.innerHeight;
  const safe = getComputedStyle(mwtSafeArea);
  const inset = (side) => parseFloat(safe[side]) || 0;
  const minX = left + inset("paddingLeft") + 16;
  const minY = top + inset("paddingTop") + 16;
  return {
    minX, minY,
    maxX: Math.max(minX, left + width - inset("paddingRight") - 16 - mwtButton.offsetWidth),
    maxY: Math.max(minY, top + height - inset("paddingBottom") - 16 - mwtButton.offsetHeight),
  };
}

// Leave a 56px floating-button column plus a 12px gap on fresh installs.
let mwtDefaultButtonOffset = 56 + 12;

function mwtPlaceButton(position = mwtButtonPosition, avoidFloatingButtons = false) {
  const bounds = mwtButtonBounds();
  // Leave 144px above the bottom margin for the composer on a fresh install.
  const preferred = position ?? { x: bounds.maxX - mwtDefaultButtonOffset, y: bounds.maxY - 144 };
  const placed = {
    x: Math.min(bounds.maxX, Math.max(bounds.minX, preferred.x)),
    y: Math.min(bounds.maxY, Math.max(bounds.minY, preferred.y)),
  };
  if (!position && avoidFloatingButtons) {
    // Look through our own button, including when the other button is below it.
    const pointerEvents = mwtButton.style.pointerEvents;
    mwtButton.style.pointerEvents = "none";
    try {
      for (let attempt = 0; attempt < 3; attempt++) {
        const hit = document.elementFromPoint(placed.x + mwtButton.offsetWidth / 2, placed.y + mwtButton.offsetHeight / 2);
        const button = hit?.closest("button, [role='button'], input[type='button'], input[type='submit']");
        if (!button || mwtButton.contains(button)) break;
        let floating = button;
        while (floating && getComputedStyle(floating).position !== "fixed") {
          floating = floating.parentElement;
        }
        if (!floating) break;
        const nextX = Math.max(bounds.minX, placed.x - mwtButton.offsetWidth);
        if (nextX === placed.x) break;
        mwtDefaultButtonOffset += placed.x - nextX;
        placed.x = nextX;
      }
    } finally {
      mwtButton.style.pointerEvents = pointerEvents;
    }
  }
  mwtButton.style.left = `${placed.x}px`;
  mwtButton.style.top = `${placed.y}px`;
  mwtButton.style.right = "auto";
  mwtButton.style.bottom = "auto";
  return placed;
}

mwtPlaceButton(mwtButtonPosition, true);
// Do not overwrite the saved preference when a keyboard or rotation shrinks
// the viewport; restore it (clamped) when the available space grows again.
marinara.on(window, "resize", () => mwtPlaceButton());
if (window.visualViewport) {
  marinara.on(window.visualViewport, "resize", () => mwtPlaceButton());
  marinara.on(window.visualViewport, "scroll", () => mwtPlaceButton());
}

let mwtDrag = null;
let mwtSuppressButtonClick = false;
// Keep Marinara's edge-swipe recognizer from starting a gesture on our button.
marinara.on(mwtButton, "touchstart", (event) => event.stopPropagation());
marinara.on(mwtButton, "pointerdown", (event) => {
  event.stopPropagation();
  if (mwtDrag || !event.isPrimary || event.button !== 0) return;
  mwtSuppressButtonClick = false;
  const rect = mwtButton.getBoundingClientRect();
  mwtDrag = { pointerId: event.pointerId, startX: event.clientX, startY: event.clientY, offsetX: event.clientX - rect.left, offsetY: event.clientY - rect.top, moved: false };
  try {
    mwtButton.setPointerCapture(event.pointerId);
  } catch {
    // best-effort
  }
});
marinara.on(window, "pointermove", (event) => {
  if (!mwtDrag || event.pointerId !== mwtDrag.pointerId) return;
  if (!mwtDrag.moved) {
    if (Math.hypot(event.clientX - mwtDrag.startX, event.clientY - mwtDrag.startY) < 6) return;
    mwtDrag.moved = true;
    mwtSuppressButtonClick = true;
    mwtButton.dataset.dragging = "true";
  }
  mwtPlaceButton({ x: event.clientX - mwtDrag.offsetX, y: event.clientY - mwtDrag.offsetY });
});
function mwtEndDrag(event) {
  if (!mwtDrag || event.pointerId !== mwtDrag.pointerId) return;
  const drag = mwtDrag;
  mwtDrag = null;
  delete mwtButton.dataset.dragging;
  if (event.type !== "pointerup") {
    mwtSuppressButtonClick = true;
    mwtPlaceButton();
  } else if (drag.moved) {
    const rect = mwtButton.getBoundingClientRect();
    mwtButtonPosition = mwtPlaceButton({ x: rect.left, y: rect.top });
    try {
      localStorage.setItem(MWT_BUTTON_POSITION_KEY, JSON.stringify(mwtButtonPosition));
    } catch {
      // Dragging remains usable when localStorage is unavailable or full.
    }
  }
  try {
    mwtButton.releasePointerCapture(event.pointerId);
  } catch {
    // already released
  }
}
marinara.on(window, "pointerup", mwtEndDrag);
marinara.on(window, "pointercancel", mwtEndDrag);
marinara.on(mwtButton, "lostpointercapture", mwtEndDrag);
marinara.on(mwtButton, "click", (event) => {
  if (mwtSuppressButtonClick && event.detail !== 0) {
    event.preventDefault();
    return;
  }
  mwtTogglePanel();
});

let mwtCurrentChatId = null;
let mwtCurrentState = null;
let mwtBusy = false;
let mwtStatusText = "";

function mwtSetStatus(text) {
  mwtStatusText = text;
  mwtRender();
}

async function mwtTogglePanel() {
  if (!mwtPanel.hidden) {
    mwtPanel.hidden = true;
    return;
  }
  mwtPanel.hidden = false;
  mwtSetStatus("채팅 확인 중...");
  const chatId = await mwtResolveActiveChatId();
  mwtCurrentChatId = chatId;
  mwtCurrentState = chatId ? mwtLoadState(chatId) : null;
  mwtSetStatus("");
}

// ── 렌더링 ──

function mwtRender() {
  if (mwtPanel.hidden) return;
  if (!mwtCurrentChatId) {
    mwtPanel.innerHTML = mwtHeaderHtml("월드마블투어") + `<div class="mwt-panel__body"><p>활성 채팅을 찾지 못했습니다. 채팅을 하나 연 뒤 다시 열어주세요.</p></div>`;
    mwtBindHeader();
    return;
  }
  if (!mwtCurrentState || mwtCurrentState.status === "setup") {
    mwtRenderSetup();
    return;
  }
  mwtRenderGame();
}

function mwtHeaderHtml(title) {
  return `
    <header class="mwt-panel__header">
      <h2 class="mwt-panel__title">${title}</h2>
      <button type="button" class="mwt-icon-button" data-mwt-close aria-label="닫기">×</button>
    </header>
  `;
}

function mwtBindHeader() {
  const closeBtn = mwtPanel.querySelector("[data-mwt-close]");
  if (closeBtn) marinara.on(closeBtn, "click", () => (mwtPanel.hidden = true));
}

function mwtRenderSetup() {
  mwtPanel.innerHTML =
    mwtHeaderHtml("월드마블투어 — 상대 선택") +
    `<div class="mwt-panel__body">
      <p>이 채팅에 참여한 캐릭터 중 함께 플레이할 상대를 고르세요.</p>
      <div class="mwt-field">
        <label for="mwt-opponent-select">상대 캐릭터</label>
        <select id="mwt-opponent-select"><option value="">불러오는 중...</option></select>
      </div>
      <button type="button" class="mwt-primary-button" data-mwt-start disabled>게임 시작</button>
      <p class="mwt-status-line" data-mwt-status></p>
    </div>`;
  mwtBindHeader();

  const select = mwtPanel.querySelector("#mwt-opponent-select");
  const startBtn = mwtPanel.querySelector("[data-mwt-start]");
  const status = mwtPanel.querySelector("[data-mwt-status]");

  (async () => {
    try {
      const chat = await mwtGetChat(mwtCurrentChatId);
      const ids = mwtParseCharacterIds(chat.characterIds);
      if (!ids.length) {
        select.innerHTML = `<option value="">이 채팅에 캐릭터가 없습니다</option>`;
        return;
      }
      const characters = await Promise.all(ids.map((id) => mwtGetCharacter(id)));
      select.innerHTML = characters
        .filter(Boolean)
        .map((c) => `<option value="${c.id}">${(c.name || c.id).replace(/</g, "&lt;")}</option>`)
        .join("");
      startBtn.disabled = !select.value;
    } catch (error) {
      select.innerHTML = `<option value="">불러오기 실패</option>`;
      status.textContent = error instanceof Error ? error.message : String(error);
    }
  })();

  marinara.on(select, "change", () => {
    startBtn.disabled = !select.value;
  });

  marinara.on(startBtn, "click", async () => {
    const characterId = select.value;
    const name = select.options[select.selectedIndex]?.textContent || "NPC";
    if (!characterId) return;
    mwtCurrentState = mwtCreateState(mwtCurrentChatId, characterId, name);
    mwtCurrentState.status = "coinflip";
    mwtSaveState(mwtCurrentState);
    await mwtRunCoinflip();
  });
}

async function mwtRunCoinflip() {
  const state = mwtCurrentState;
  mwtSetStatus("선공을 정하는 중...");
  const human = mwtSeat(state, "seat-1");
  const npc = mwtSeat(state, "seat-2");
  let a = mwtRollDie(6);
  let b = mwtRollDie(6);
  while (a === b) {
    a = mwtRollDie(6);
    b = mwtRollDie(6);
  }
  const humanFirst = a > b;
  state.turnOrder = humanFirst ? ["seat-1", "seat-2"] : ["seat-2", "seat-1"];
  state.currentTurnIndex = 0;
  state.status = "in_progress";
  mwtLog(state, `선공 결정: ${human.label}(${a}) vs ${npc.label}(${b}) — ${humanFirst ? human.label : npc.label} 선공.`);
  mwtSaveState(state);
  try {
    await mwtPostMessage(
      state.chatId,
      "narrator",
      `[월드마블투어 시작] ${human.label}(${a}) vs ${npc.label}(${b}) — ${humanFirst ? human.label : npc.label}이(가) 선공입니다. 시작 자금 각 ₩2,000,000.`,
      null,
    );
  } catch (error) {
    console.warn("[월드마블투어] 시작 메시지 전송 실패", error);
  }
  mwtSetStatus("");
  mwtRender();
  await mwtMaybeAutoPlayCharacterTurn();
  mwtAfterTurnRefresh();
}

// MWT_TILE_POS 퍼센트 좌표(원본 리루 JSX에서 그대로 가져옴)를 이용해 보드
// 이미지 위에 플레이어 토큰과 소유권 마커를 절대 위치로 얹는다.
function mwtBoardImageHtml(state) {
  const current = mwtCurrentSeat(state);
  const samePos = state.seats[0].position === state.seats[1].position;
  const tokens = state.seats
    .map((seat, idx) => {
      const pos = MWT_TILE_POS[seat.position];
      const offsetX = samePos ? (idx === 0 ? -3 : 3) : 0;
      const active = seat.id === current.id && state.status === "in_progress";
      return `<div class="mwt-board-token${active ? " mwt-board-token--active" : ""}" style="left:${pos.x + offsetX}%; top:${pos.y}%;" title="${seat.label}">${seat.kind === "human" ? "🙂" : "🤖"}</div>`;
    })
    .join("");
  const owners = Object.entries(state.owned)
    .map(([tileNumStr, entry]) => {
      const tileNum = Number(tileNumStr);
      const pos = MWT_TILE_POS[tileNum];
      const seat = mwtSeat(state, entry.seatId);
      const icon = MWT_BUILD_ICON[entry.level] || "🔹";
      return `<div class="mwt-board-owner" data-owner="${entry.seatId}" style="left:${pos.x}%; top:${pos.y + 9}%;" title="${seat.label} 소유">${icon}</div>`;
    })
    .join("");
  return `<div class="mwt-board-image" style="background-image:url('${MWT_BOARD_DATA_URI}')">${tokens}${owners}</div>`;
}

function mwtRenderGame() {
  const state = mwtCurrentState;
  const current = mwtCurrentSeat(state);
  const pending = state.pendingDecision;

  const boardHtml =
    MWT_BOARD_DATA_URI == null
      ? `<div class="mwt-board-list">${Array.from({ length: MWT_TILE_COUNT }, (_, i) => i + 1).map((n) => mwtTileRowHtml(state, n)).join("")}</div><p class="mwt-board-note">보드 이미지 준비 전까지 목록으로 표시합니다.</p>`
      : mwtBoardImageHtml(state);

  const hudHtml = state.seats
    .map(
      (seat) => `
      <div class="mwt-hud-row" data-turn="${seat.id === current.id}">
        <div>
          <div class="mwt-hud-name">${seat.kind === "human" ? "🙂" : "🤖"} ${seat.label}${seat.id === current.id ? " ◀" : ""}</div>
          <div class="mwt-hud-sub">💰 ₩${mwtFmt(seat.cash)} · 📍 ${mwtTileLabel(seat.position)}${seat.islandTurnsLeft > 0 ? ` · 🏝 ${seat.islandTurnsLeft}턴 정지` : ""}${seat.freePassCount > 0 ? ` · 🎫x${seat.freePassCount}` : ""}</div>
        </div>
      </div>`,
    )
    .join("");

  let actionHtml;
  if (state.status === "finished") {
    actionHtml = `<p><strong>게임 종료.</strong></p><button type="button" class="mwt-secondary-button" data-mwt-reset>새 게임 시작</button>`;
  } else if (pending && pending.seatId === "seat-1") {
    actionHtml = mwtDecisionHtml(pending);
  } else if (current.kind === "human" && !pending) {
    actionHtml = `
      <div class="mwt-dice-row">
        <span class="mwt-die" data-mwt-d1>?</span><span class="mwt-die" data-mwt-d2>?</span>
      </div>
      <button type="button" class="mwt-primary-button" data-mwt-roll ${mwtBusy ? "disabled" : ""}>🎲 굴리기</button>`;
  } else {
    actionHtml = `<p class="mwt-status-line">${current.label} 턴 진행 중...</p>`;
  }

  const logHtml = state.log
    .slice(-12)
    .reverse()
    .map((entry) => `<div>#${entry.turn} ${entry.text.replace(/</g, "&lt;")}</div>`)
    .join("");

  mwtPanel.innerHTML =
    mwtHeaderHtml("월드마블투어") +
    `<div class="mwt-panel__body">
      ${boardHtml}
      <div class="mwt-hud-list">${hudHtml}</div>
      <div data-mwt-action>${actionHtml}</div>
      <p class="mwt-status-line" data-mwt-status>${mwtStatusText}</p>
      <div class="mwt-log">${logHtml}</div>
      <div class="mwt-toggle-row">
        <label><input type="checkbox" data-mwt-autorefresh ${state.settings.autoRefresh ? "checked" : ""}> 턴마다 자동 새로고침</label>
      </div>
      <div class="mwt-footer-row">
        <button type="button" class="mwt-secondary-button" data-mwt-refresh>🔄 채팅창 새로고침</button>
        <button type="button" class="mwt-secondary-button" data-mwt-reset>게임 초기화</button>
      </div>
    </div>`;

  mwtBindHeader();
  mwtBindGameActions();
}

function mwtTileRowHtml(state, tileNum) {
  const owned = state.owned[tileNum];
  const tile = MWT_TILES[tileNum];
  const tokens = state.seats.filter((s) => s.position === tileNum).map((s) => `<span class="mwt-token-chip">${s.kind === "human" ? "🙂" : "🤖"}</span>`).join("");
  const isCurrent = mwtCurrentSeat(state).position === tileNum;
  const ownerLabel = owned ? ` (${mwtSeat(state, owned.seatId).label}${MWT_BUILD_ICON[owned.level] ? " " + MWT_BUILD_ICON[owned.level] : ""})` : "";
  return `<div class="mwt-board-tile" data-current="${isCurrent}"><span>${mwtTileLabel(tileNum)}${tile.price ? ` ₩${mwtFmt(tile.price)}` : ""}${ownerLabel}</span><span class="mwt-tile-tokens">${tokens}</span></div>`;
}

function mwtDecisionHtml(decision) {
  if (decision.kind === "buy") {
    return `<div class="mwt-decision-box"><p>${mwtTileLabel(decision.tileNum)}을(를) ₩${mwtFmt(decision.price)}에 구매할까요?</p><div class="mwt-decision-choices">
      <button type="button" class="mwt-primary-button" data-mwt-decide="yes">구매</button>
      <button type="button" class="mwt-secondary-button" data-mwt-decide="no">패스</button>
    </div></div>`;
  }
  if (decision.kind === "build") {
    return `<div class="mwt-decision-box"><p>${mwtTileLabel(decision.tileNum)}에 ${MWT_BUILD_ICON[decision.nextLevel]} 건설? (₩${mwtFmt(decision.nextCost)})</p><div class="mwt-decision-choices">
      <button type="button" class="mwt-primary-button" data-mwt-decide="yes">건설</button>
      <button type="button" class="mwt-secondary-button" data-mwt-decide="no">패스</button>
    </div></div>`;
  }
  if (decision.kind === "worldtour") {
    const options = Array.from({ length: MWT_TILE_COUNT }, (_, i) => i + 1)
      .filter((n) => n !== decision.tileNum)
      .map((n) => `<option value="${n}">${mwtTileLabel(n)}</option>`)
      .join("");
    return `<div class="mwt-decision-box"><p>세계여행 목적지를 고르세요.</p>
      <select data-mwt-worldtour-select>${options}</select>
      <button type="button" class="mwt-primary-button" data-mwt-decide-worldtour>이동</button>
    </div>`;
  }
  return "";
}

function mwtBindGameActions() {
  const rollBtn = mwtPanel.querySelector("[data-mwt-roll]");
  if (rollBtn) marinara.on(rollBtn, "click", () => void mwtHandleHumanRoll());

  for (const btn of mwtPanel.querySelectorAll("[data-mwt-decide]")) {
    marinara.on(btn, "click", () => void mwtHandleHumanDecision(btn.dataset.mwtDecide));
  }
  const worldtourBtn = mwtPanel.querySelector("[data-mwt-decide-worldtour]");
  if (worldtourBtn) {
    marinara.on(worldtourBtn, "click", () => {
      const select = mwtPanel.querySelector("[data-mwt-worldtour-select]");
      void mwtHandleHumanDecision(select.value);
    });
  }

  const resetBtn = mwtPanel.querySelector("[data-mwt-reset]");
  if (resetBtn) {
    marinara.on(resetBtn, "click", () => {
      mwtClearState(mwtCurrentChatId);
      mwtCurrentState = null;
      mwtRender();
    });
  }

  const refreshBtn = mwtPanel.querySelector("[data-mwt-refresh]");
  if (refreshBtn) marinara.on(refreshBtn, "click", () => window.location.reload());

  const autoRefreshBox = mwtPanel.querySelector("[data-mwt-autorefresh]");
  if (autoRefreshBox) {
    marinara.on(autoRefreshBox, "change", () => {
      mwtCurrentState.settings.autoRefresh = autoRefreshBox.checked;
      mwtSaveState(mwtCurrentState);
    });
  }
}

function mwtAfterTurnRefresh() {
  if (mwtLifecycle.disposed) return; // 비활성화 후 잔류 작업이 페이지를 새로고침하지 않도록
  if (mwtCurrentState && mwtCurrentState.settings.autoRefresh) {
    window.location.reload();
  }
}

// ── 턴 진행 ──

async function mwtHandleHumanRoll() {
  const state = mwtCurrentState;
  if (mwtBusy || state.status !== "in_progress") return;
  const seat = mwtCurrentSeat(state);
  if (seat.kind !== "human" || state.pendingDecision) return;

  mwtBusy = true;
  mwtSetStatus("주사위 굴리는 중...");
  const { d1, d2, sum, isDouble } = mwtRollDice();
  const d1el = mwtPanel.querySelector("[data-mwt-d1]");
  const d2el = mwtPanel.querySelector("[data-mwt-d2]");
  if (d1el) d1el.textContent = String(d1);
  if (d2el) d2el.textContent = String(d2);

  try {
    await mwtResolveDiceOutcome(state, seat, d1, d2, sum, isDouble);
  } catch (error) {
    mwtSetStatus(error instanceof Error ? error.message : String(error));
  } finally {
    mwtBusy = false;
    mwtSaveState(state);
    mwtRender();
  }
}

async function mwtResolveDiceOutcome(state, seat, d1, d2, sum, isDouble) {
  state.turnNumber += 1;

  if (seat.islandTurnsLeft > 0) {
    if (isDouble) {
      seat.islandTurnsLeft = 0;
      mwtLog(state, `${seat.label} 주사위 ${d1}+${d2} — 더블! 무인도에서 탈출합니다 (추가 턴 없음).`);
      await mwtPostMessage(state.chatId, "narrator", `${seat.label}가 무인도에서 더블을 굴려 탈출했습니다.`, null);
    } else {
      seat.islandTurnsLeft -= 1;
      mwtLog(state, `${seat.label} 주사위 ${d1}+${d2} — 무인도 대기 (남은 턴 ${seat.islandTurnsLeft}).`);
      await mwtPostMessage(state.chatId, "narrator", `${seat.label}가 무인도에서 대기 중입니다 (남은 턴 ${seat.islandTurnsLeft}).`, null);
    }
    mwtEndTurn(state);
    await mwtMaybeAutoPlayCharacterTurn();
    mwtAfterTurnRefresh();
    return;
  }

  const move = mwtMoveSeat(state, seat.id, sum);
  const lines = [`${seat.label} 주사위 ${d1}+${d2}=${sum}${isDouble ? " (더블!)" : ""} — ${mwtTileLabel(move.from)} → ${mwtTileLabel(move.to)}`];
  if (move.passedStart) lines.push(`출발 통과 +₩${mwtFmt(MWT_START_BONUS)}`);
  const landing = mwtResolveTile(state, seat.id);
  lines.push(landing.text);
  mwtLog(state, lines.join(" / "));
  await mwtPostMessage(state.chatId, "narrator", lines.join("\n"), null);

  if (landing.decision) {
    state.pendingDecision = { ...landing.decision, seatId: seat.id, isDouble };
    mwtSaveState(state);
    mwtRender();
    return; // 사람 턴이면 UI에서 버튼을 눌러 mwtHandleHumanDecision으로 이어짐
  }

  if (mwtCheckAndHandleGameEnd(state)) return;

  if (isDouble) {
    mwtLog(state, `더블! ${seat.label}가 한 번 더 굴립니다.`);
    return; // 같은 사람이 다시 굴리기 버튼을 누름
  }

  mwtEndTurn(state);
  await mwtMaybeAutoPlayCharacterTurn();
  mwtAfterTurnRefresh();
}

async function mwtHandleHumanDecision(value) {
  const state = mwtCurrentState;
  const decision = state.pendingDecision;
  if (!decision || decision.seatId !== "seat-1") return;
  mwtBusy = true;
  mwtSetStatus("처리 중...");
  try {
    const { text, followUpDecision } = mwtApplyDecision(state, decision.seatId, decision, value);
    mwtLog(state, text);
    state.pendingDecision = null;
    await mwtPostMessage(state.chatId, "narrator", text, null);

    if (mwtCheckAndHandleGameEnd(state)) return;

    if (followUpDecision) {
      // 세계여행으로 도착한 칸이 그 자체로 구매/건설을 요구하는 경우 — 같은
      // 사람의 pendingDecision으로 이어 붙인다 (더블 여부도 그대로 유지).
      state.pendingDecision = { ...followUpDecision, seatId: decision.seatId, isDouble: decision.isDouble };
      return;
    }

    if (decision.isDouble) {
      mwtLog(state, `더블! ${mwtSeat(state, decision.seatId).label}가 한 번 더 굴립니다.`);
      return; // 같은 사람이 다시 굴리기 버튼을 누름
    }

    mwtEndTurn(state);
    await mwtMaybeAutoPlayCharacterTurn();
    mwtAfterTurnRefresh();
  } catch (error) {
    mwtSetStatus(error instanceof Error ? error.message : String(error));
  } finally {
    mwtBusy = false;
    mwtSaveState(state);
    mwtRender();
  }
}

function mwtCheckAndHandleGameEnd(state) {
  return state.status === "finished";
}

function mwtEndTurn(state) {
  state.currentTurnIndex = (state.currentTurnIndex + 1) % state.turnOrder.length;
}

// NPC 턴을 끝까지 자동 진행한다 (주사위 → 착지 처리 → 필요 시 태그 프로토콜로
// 결정 요청 → 더블이면 반복). 사람 턴이 되거나 게임이 끝나면 반환한다.
async function mwtMaybeAutoPlayCharacterTurn() {
  const state = mwtCurrentState;
  if (!state || state.status !== "in_progress") return;
  let seat = mwtCurrentSeat(state);
  while (seat && seat.kind === "character" && state.status === "in_progress") {
    mwtSetStatus(`${seat.label} 턴 진행 중...`);
    mwtRender();
    state.turnNumber += 1;
    const { d1, d2, sum, isDouble } = mwtRollDice();

    if (seat.islandTurnsLeft > 0) {
      if (isDouble) {
        seat.islandTurnsLeft = 0;
        mwtLog(state, `${seat.label} 주사위 ${d1}+${d2} — 더블! 무인도에서 탈출합니다.`);
      } else {
        seat.islandTurnsLeft -= 1;
        mwtLog(state, `${seat.label} 주사위 ${d1}+${d2} — 무인도 대기 (남은 턴 ${seat.islandTurnsLeft}).`);
      }
      try {
        await mwtPostMessage(state.chatId, "narrator", state.log[state.log.length - 1].text, null);
      } catch (error) {
        console.warn("[월드마블투어] 메시지 전송 실패", error);
      }
      mwtEndTurn(state);
      mwtSaveState(state);
      seat = mwtCurrentSeat(state);
      continue;
    }

    const move = mwtMoveSeat(state, seat.id, sum);
    const lines = [`${seat.label} 주사위 ${d1}+${d2}=${sum}${isDouble ? " (더블!)" : ""} — ${mwtTileLabel(move.from)} → ${mwtTileLabel(move.to)}`];
    if (move.passedStart) lines.push(`출발 통과 +₩${mwtFmt(MWT_START_BONUS)}`);
    const landing = mwtResolveTile(state, seat.id);
    lines.push(landing.text);
    mwtLog(state, lines.join(" / "));
    mwtSaveState(state);

    try {
      await mwtPostMessage(state.chatId, "narrator", lines.join("\n"), null);
    } catch (error) {
      console.warn("[월드마블투어] 메시지 전송 실패", error);
    }

    let pendingNpcDecision = landing.decision;
    while (pendingNpcDecision) {
      try {
        const { value, dialogue } = await mwtRequestCharacterDecision(state, seat, pendingNpcDecision);
        if (dialogue) mwtLog(state, `💬 ${seat.label}: ${dialogue}`);
        const { text, followUpDecision } = mwtApplyDecision(state, seat.id, pendingNpcDecision, value);
        mwtLog(state, text);
        await mwtPostMessage(state.chatId, "narrator", text, null);
        pendingNpcDecision = followUpDecision; // 세계여행이 또 다른 결정을 요구하면 계속 이어감
      } catch (error) {
        console.warn("[월드마블투어] 캐릭터 결정 요청 실패", error);
        mwtLog(state, `${seat.label}의 결정을 받아오지 못해 패스로 처리합니다.`);
        pendingNpcDecision = null;
      }
    }

    mwtSaveState(state);
    if (mwtCheckAndHandleGameEnd(state)) return;

    if (isDouble) {
      mwtRender();
      continue; // 같은 좌석이 계속 진행 (무인도 탈출은 위에서 이미 처리 후 continue)
    }

    mwtEndTurn(state);
    mwtSaveState(state);
    seat = mwtCurrentSeat(state);
  }
  mwtSetStatus("");
}

mwtRender();
